{{--
    Footer Component
    
    Reusable site-wide footer with brand, services, company links, and contact information.
    
    Props:
    - $tagline (string): Brand tagline
    - $serviceLinks (array): Array of service links ['text' => '', 'url' => '']
    - $companyLinks (array): Array of company links ['text' => '', 'url' => '']
    
    ACF Fields Used:
    - {acf:footer_tagline} - Brand tagline
    - {acf:footer_phone} - Contact phone
    - {acf:footer_email} - Contact email
    - {acf:footer_address_line_1} - Street address
    - {acf:footer_address_line_2} - City, state, zip
    - {acf:footer_business_hours} - Business hours text
    - {acf:footer_copyright_year} - Copyright year
--}}

@php
    $tagline = $tagline ?? 'Your trusted partner for home comfort in Charlottesville for over 30 years.'; // {acf:footer_tagline}
    $phone = $phone ?? '(434) 979-4328'; // {acf:footer_phone}
    $email = $email ?? 'info@airflow-hvac.com'; // {acf:footer_email}
    $addressLine1 = $addressLine1 ?? '1134 Rose Hill Drive'; // {acf:footer_address_line_1}
    $addressLine2 = $addressLine2 ?? 'Charlottesville, VA 22903'; // {acf:footer_address_line_2}
    $businessHours = $businessHours ?? 'Monday–Friday: 7:30AM–4:00PM'; // {acf:footer_business_hours}
    $businessHours2 = $businessHours2 ?? 'Sat.–Sunday: Closed'; // {acf:footer_business_hours_2}
    $copyrightYear = $copyrightYear ?? date('Y'); // {acf:footer_copyright_year}
    
    $defaultServiceLinks = [
        ['text' => 'Heating Systems', 'url' => '/services'],
        ['text' => 'Air Conditioning', 'url' => '/ac-installation'],
        ['text' => 'Maintenance Plans', 'url' => '/maintenance'],
        ['text' => 'Geothermal', 'url' => '/geothermal-systems'],
        ['text' => 'Emergency Repair', 'url' => '#emergency'],
        ['text' => 'Installation', 'url' => '/heat-pump-installation'],
    ];
    
    $defaultCompanyLinks = [
        ['text' => 'About Us', 'url' => '/about-us'],
        ['text' => 'Testimonials', 'url' => '#testimonials'],
        ['text' => 'Service Area', 'url' => '#service-area'],
        ['text' => 'Careers', 'url' => '/job-opportunities'],
        ['text' => 'Financing Options', 'url' => '#financing'],
        ['text' => 'Contact', 'url' => '#contact'],
    ];
    
    $serviceLinks = $serviceLinks ?? $defaultServiceLinks;
    $companyLinks = $companyLinks ?? $defaultCompanyLinks;
@endphp

